const menuToggle = document.querySelector('.menu-toggle');
const mobileNav = document.querySelector('.mobile-nav');
menuToggle?.addEventListener('click', () => { const open = mobileNav.classList.toggle('open'); menuToggle.setAttribute('aria-expanded', String(open)); });
mobileNav?.querySelectorAll('a').forEach(link => link.addEventListener('click', () => { mobileNav.classList.remove('open'); menuToggle.setAttribute('aria-expanded', 'false'); }));
window.addEventListener('load', () => document.body.classList.add('page-loaded'));
const revealObserver = new IntersectionObserver(entries => entries.forEach(entry => { if (entry.isIntersecting) { entry.target.classList.add('visible'); revealObserver.unobserve(entry.target); } }), { threshold: .12 });
document.querySelectorAll('.reveal').forEach(el => revealObserver.observe(el));
const progress = document.querySelector('.scroll-progress');
const updateProgress = () => { const max = document.documentElement.scrollHeight - window.innerHeight; if (progress && max > 0) progress.style.transform = `scaleX(${window.scrollY / max})`; };
window.addEventListener('scroll', updateProgress, { passive: true }); updateProgress();
const sectionLinks = [...document.querySelectorAll('.nav-links a, .mobile-nav a')];
const sectionObserver = new IntersectionObserver(entries => entries.forEach(entry => { if (entry.isIntersecting) sectionLinks.forEach(link => link.classList.toggle('active', link.getAttribute('href') === `#${entry.target.id}`)); }), { rootMargin: '-35% 0px -55% 0px', threshold: 0 });
document.querySelectorAll('main section[id]').forEach(section => sectionObserver.observe(section));
const glow = document.querySelector('.cursor-glow');
if (glow && window.matchMedia('(pointer: fine)').matches && !window.matchMedia('(prefers-reduced-motion: reduce)').matches) { window.addEventListener('pointermove', event => { glow.style.transform = `translate3d(${event.clientX - 90}px, ${event.clientY - 90}px, 0)`; }); }
document.querySelectorAll('.skill-card, .info-card, .project-visual, .github-panel').forEach(card => { card.addEventListener('pointermove', event => { if (!window.matchMedia('(pointer: fine)').matches || window.matchMedia('(prefers-reduced-motion: reduce)').matches) return; const rect = card.getBoundingClientRect(); const x = (event.clientX - rect.left) / rect.width - .5; const y = (event.clientY - rect.top) / rect.height - .5; card.style.setProperty('--rx', `${y * -3}deg`); card.style.setProperty('--ry', `${x * 3}deg`); card.classList.add('is-tilting'); }); card.addEventListener('pointerleave', () => { card.classList.remove('is-tilting'); card.style.removeProperty('--rx'); card.style.removeProperty('--ry'); }); });
document.querySelectorAll('.button, .text-link, .email-link').forEach(link => { link.addEventListener('pointerenter', () => document.body.classList.add('interactive-hover')); link.addEventListener('pointerleave', () => document.body.classList.remove('interactive-hover')); });
const form = document.querySelector('#contact-form');
const status = document.querySelector('.form-status');
form?.addEventListener('submit', event => { event.preventDefault(); const data = new FormData(form); const subject = encodeURIComponent(`Portfolio enquiry from ${data.get('name')}`); const body = encodeURIComponent(`${data.get('message')}\n\nReply to: ${data.get('email')}`); window.location.href = `mailto:tahasaadat680@gmail.com?subject=${subject}&body=${body}`; status.textContent = 'Opening your email client — thank you.'; });
